  "Export selected PDF": { de: "Ausgewählte als PDF exportieren", es: "Exportar selección en PDF", sq: "Eksporto të përzgjedhurat në PDF", ar: "تصدير المحدد إلى PDF", pt: "Exportar seleção em PDF", it: "Esporta selezionati in PDF", ru: "Экспортировать выбранное в PDF" },
  "Export transaction history": { de: "Transaktionsverlauf exportieren", es: "Exportar historial de transacciones", sq: "Eksporto historikun e transaksioneve", ar: "تصدير سجل المعاملات", pt: "Exportar histórico de transações", it: "Esporta cronologia transazioni", ru: "Экспортировать историю транзакций" },
