  "Invitation required.": { de: "Einladung erforderlich.", es: "Se requiere invitación.", sq: "Kërkohet ftesë.", ar: "الدعوة مطلوبة.", pt: "Convite necessário.", it: "Invito richiesto.", ru: "Требуется приглашение." },
