  "Invoice or order reference": { de: "Rechnungs- oder Bestellreferenz", es: "Referencia de factura o pedido", sq: "Referenca e faturës ose porosisë", ar: "مرجع الفاتورة أو الطلب", pt: "Referência de fatura ou encomenda", it: "Riferimento fattura o ordine", ru: "Ссылка на счёт или заказ" },
  "Invoice or receipt": { de: "Rechnung oder Beleg", es: "Factura o recibo", sq: "Faturë ose kupon", ar: "فاتورة أو إيصال", pt: "Fatura ou recibo", it: "Fattura o ricevuta", ru: "Счёт или квитанция" },
  "Invoice prefix": { de: "Rechnungspräfix", es: "Prefijo de factura", sq: "Prefiksi i faturës", ar: "بادئة الفاتورة", pt: "Prefixo da fatura", it: "Prefisso fattura", ru: "Префикс счёта" },
  "is required for this feature. Upgrade below to unlock it immediately after PayPal confirms the subscription.": { de: "ist für diese Funktion erforderlich. Führe unten ein Upgrade durch, um sie unmittelbar freizuschalten, nachdem PayPal das Abonnement bestätigt hat.", es: "es obligatorio para esta función. Actualiza abajo para desbloquearla inmediatamente después de que PayPal confirme la suscripción.", sq: "kërkohet për këtë veçori. Përmirëso më poshtë për ta zhbllokuar menjëherë pasi PayPal të konfirmojë abonimin.", ar: "مطلوب لهذه الميزة. قم بالترقية أدناه لفتحها فورًا بعد أن يؤكد PayPal الاشتراك.", pt: "é necessário para esta funcionalidade. Faça o upgrade abaixo para a desbloquear imediatamente após o PayPal confirmar a subscrição.", it: "è richiesto per questa funzione. Esegui l'upgrade qui sotto per sbloccarla immediatamente dopo la conferma dell'abbonamento da parte di PayPal.", ru: "требуется для этой функции. Обновите план ниже, чтобы разблокировать её сразу после подтверждения подписки PayPal." },
  "Issue date": { de: "Ausstellungsdatum", es: "Fecha de emisión", sq: "Data e lëshimit", ar: "تاريخ الإصدار", pt: "Data de emissão", it: "Data di emissione", ru: "Дата выдачи" },
