  "Large upcoming expense warning": { de: "Warnung vor großer bevorstehender Ausgabe", es: "Aviso de gran gasto próximo", sq: "Paralajmërim për shpenzim të madh të ardhshëm", ar: "تحذير من مصروف كبير قادم", pt: "Aviso de grande despesa próxima", it: "Avviso grande spesa imminente", ru: "Предупреждение о крупном предстоящем расходе" },
