  "Linked supplier spend": { de: "Ausgaben bei verknüpften Lieferanten", es: "Gasto de proveedores vinculados", sq: "Shpenzimet te furnitorët e lidhur", ar: "إنفاق الموردين المرتبطين", pt: "Despesa de fornecedores associados", it: "Spesa fornitori collegati", ru: "Расходы по связанным поставщикам" },
  "Live = visible and active during the last 2 minutes. Idle tracking stops after 5 minutes.": { de: "Live = sichtbar und aktiv in den letzten 2 Minuten. Die Leerlaufverfolgung endet nach 5 Minuten.", es: "En vivo = visible y activo durante los últimos 2 minutos. El seguimiento de inactividad se detiene después de 5 minutos.", sq: "Drejtpërdrejt = i dukshëm dhe aktiv gjatë 2 minutave të fundit. Gjurmimi i pasivitetit ndalet pas 5 minutash.", ar: "مباشر = ظاهر ونشط خلال آخر دقيقتين. يتوقف تتبع الخمول بعد 5 دقائق.", pt: "Em direto = visível e ativo durante os últimos 2 minutos. O acompanhamento de inatividade termina após 5 minutos.", it: "Live = visibile e attivo negli ultimi 2 minuti. Il monitoraggio dell'inattività si interrompe dopo 5 minuti.", ru: "В реальном времени = видим и активен в последние 2 минуты. Отслеживание простоя прекращается через 5 минут." },
  "Live activity": { de: "Live-Aktivität", es: "Actividad en vivo", sq: "Aktivitet drejtpërdrejt", ar: "نشاط مباشر", pt: "Atividade em direto", it: "Attività live", ru: "Активность в реальном времени" },
  "LIVE BUSINESS LEDGER": { de: "LIVE-GESCHÄFTSHAUPTBUCH", es: "LIBRO MAYOR EMPRESARIAL EN VIVO", sq: "LIBRI I BIZNESIT DREJTPËRDREJT", ar: "دفتر أعمال مباشر", pt: "RAZÃO EMPRESARIAL EM DIRETO", it: "REGISTRO AZIENDALE LIVE", ru: "БИЗНЕС-РЕЕСТР В РЕАЛЬНОМ ВРЕМЕНИ" },
  "Live guidance": { de: "Live-Empfehlungen", es: "Orientación en vivo", sq: "Udhëzime drejtpërdrejt", ar: "إرشادات مباشرة", pt: "Orientação em direto", it: "Indicazioni live", ru: "Рекомендации в реальном времени" },
  "Live synchronization": { de: "Live-Synchronisierung", es: "Sincronización en vivo", sq: "Sinkronizim drejtpërdrejt", ar: "مزامنة مباشرة", pt: "Sincronização em direto", it: "Sincronizzazione live", ru: "Синхронизация в реальном времени" },
  "Live transaction history. The newest ten transactions are visible first; scroll for older records.": { de: "Live-Transaktionsverlauf. Die neuesten zehn Transaktionen werden zuerst angezeigt; für ältere Einträge scrollen.", es: "Historial de transacciones en vivo. Las diez transacciones más recientes aparecen primero; desplázate para ver registros anteriores.", sq: "Historiku i transaksioneve drejtpërdrejt. Dhjetë transaksionet më të reja shfaqen të parat; lëviz poshtë për regjistrimet më të vjetra.", ar: "سجل المعاملات المباشر. تظهر أحدث عشر معاملات أولًا؛ مرّر لعرض السجلات الأقدم.", pt: "Histórico de transações em tempo real. As dez transações mais recentes aparecem primeiro; desloque para ver registos mais antigos.", it: "Cronologia delle transazioni in tempo reale. Le dieci transazioni più recenti sono visibili per prime; scorri per i record precedenti.", ru: "История транзакций в реальном времени. Сначала показаны десять самых новых транзакций; прокрутите для просмотра более старых записей." },
  "Load 120 more": { de: "120 weitere laden", es: "Cargar 120 más", sq: "Ngarko edhe 120", ar: "تحميل 120 أخرى", pt: "Carregar mais 120", it: "Carica altre 120", ru: "Загрузить ещё 120" },
  "Load a familiar entry, check it, and save.": { de: "Einen vertrauten Eintrag laden, prüfen und speichern.", es: "Carga una entrada conocida, revísala y guárdala.", sq: "Ngarko një regjistrim të njohur, kontrolloje dhe ruaje.", ar: "حمّل إدخالًا مألوفًا، راجعه واحفظه.", pt: "Carregue uma entrada conhecida, verifique-a e guarde-a.", it: "Carica una voce già nota, controllala e salvala.", ru: "Загрузите знакомую запись, проверьте её и сохраните." },
  "Loading billing history…": { de: "Abrechnungsverlauf wird geladen…", es: "Cargando historial de facturación…", sq: "Po ngarkohet historiku i faturimit…", ar: "جارٍ تحميل سجل الفوترة…", pt: "A carregar histórico de faturação…", it: "Caricamento della cronologia di fatturazione…", ru: "Загрузка истории выставления счетов…" },
  "Loading notifications…": { de: "Benachrichtigungen werden geladen…", es: "Cargando notificaciones…", sq: "Po ngarkohen njoftimet…", ar: "جارٍ تحميل الإشعارات…", pt: "A carregar notificações…", it: "Caricamento delle notifiche…", ru: "Загрузка уведомлений…" },
  "Loading your vault…": { de: "Ihr Tresor wird geladen…", es: "Cargando tu bóveda…", sq: "Po ngarkohet kasaforta jote…", ar: "جارٍ تحميل خزنتك…", pt: "A carregar o seu cofre…", it: "Caricamento del tuo archivio protetto…", ru: "Загрузка вашего хранилища…" },
