  "Locked after financial activity begins.": { de: "Nach Beginn finanzieller Aktivität gesperrt.", es: "Bloqueado después de que comience la actividad financiera.", sq: "Bllokohet pasi fillon aktiviteti financiar.", ar: "يُقفل بعد بدء النشاط المالي.", pt: "Bloqueado após o início da atividade financeira.", it: "Bloccato dopo l'inizio dell'attività finanziaria.", ru: "Блокируется после начала финансовой активности." },
  "Log out from all devices": { de: "Von allen Geräten abmelden", es: "Cerrar sesión en todos los dispositivos", sq: "Dil nga llogaria në të gjitha pajisjet", ar: "تسجيل الخروج من جميع الأجهزة", pt: "Terminar sessão em todos os dispositivos", it: "Disconnetti da tutti i dispositivi", ru: "Выйти на всех устройствах" },
  "Logging out…": { de: "Abmeldung läuft…", es: "Cerrando sesión…", sq: "Po dilni nga llogaria…", ar: "جارٍ تسجيل الخروج…", pt: "A terminar sessão…", it: "Disconnessione in corso…", ru: "Выполняется выход…" },
  "Login email": { de: "Anmelde-E-Mail", es: "Correo electrónico de inicio de sesión", sq: "Email-i i hyrjes", ar: "البريد الإلكتروني لتسجيل الدخول", pt: "E-mail de início de sessão", it: "Email di accesso", ru: "Электронная почта для входа" },
  "Long-term goal funding": { de: "Finanzierung langfristiger Ziele", es: "Financiación de objetivos a largo plazo", sq: "Financimi i objektivave afatgjata", ar: "تمويل الأهداف طويلة الأجل", pt: "Financiamento de objetivos de longo prazo", it: "Finanziamento degli obiettivi a lungo termine", ru: "Финансирование долгосрочных целей" },
  "LONG-TERM PLANNING": { de: "LANGFRISTIGE PLANUNG", es: "PLANIFICACIÓN A LARGO PLAZO", sq: "PLANIFIKIM AFATGJATË", ar: "التخطيط طويل الأجل", pt: "PLANEAMENTO DE LONGO PRAZO", it: "PIANIFICAZIONE A LUNGO TERMINE", ru: "ДОЛГОСРОЧНОЕ ПЛАНИРОВАНИЕ" },
  "Long-term scoring": { de: "Langfristige Bewertung", es: "Puntuación a largo plazo", sq: "Vlerësimi afatgjatë", ar: "التقييم طويل الأجل", pt: "Pontuação de longo prazo", it: "Valutazione a lungo termine", ru: "Долгосрочная оценка" },
