  "Low stock alerts": { de: "Warnungen bei niedrigem Bestand", es: "Alertas de stock bajo", sq: "Njoftime për stok të ulët", ar: "تنبيهات انخفاض المخزون", pt: "Alertas de stock baixo", it: "Avvisi scorte basse", ru: "Оповещения о низком запасе" },
  "Low-stock alerts": { de: "Warnungen bei niedrigem Bestand", es: "Alertas de stock bajo", sq: "Njoftime për stok të ulët", ar: "تنبيهات انخفاض المخزون", pt: "Alertas de stock baixo", it: "Avvisi scorte basse", ru: "Оповещения о низком запасе" },
