  "Mark all read": { de: "Alle als gelesen markieren", es: "Marcar todo como leído", sq: "Shënoji të gjitha si të lexuara", ar: "تحديد الكل كمقروء", pt: "Marcar tudo como lido", it: "Segna tutto come letto", ru: "Отметить всё как прочитанное" },
