  "No goals tracked": { de: "Keine Ziele verfolgt", es: "No hay objetivos seguidos", sq: "Asnjë objektiv i ndjekur", ar: "لا توجد أهداف قيد المتابعة", pt: "Nenhum objetivo acompanhado", it: "Nessun obiettivo monitorato", ru: "Цели не отслеживаются" },
