  "Total saved in the last": { de: "Gesamt gespart in den letzten", es: "Total ahorrado en los últimos", sq: "Totali i kursyer në", ar: "إجمالي المدخر في آخر", pt: "Total poupado nos últimos", it: "Totale risparmiato negli ultimi", ru: "Всего накоплено за последние" },
