  "Total users": { de: "Benutzer insgesamt", es: "Total de usuarios", sq: "Përdoruesit totalë", ar: "إجمالي المستخدمين", pt: "Total de utilizadores", it: "Totale utenti", ru: "Всего пользователей" },
  "Track progress, record investments and payments, and keep every movement synchronized.": { de: "Fortschritt verfolgen, Investitionen und Zahlungen erfassen und jede Bewegung synchron halten.", es: "Sigue el progreso, registra inversiones y pagos y mantén cada movimiento sincronizado.", sq: "Ndiq progresin, regjistro investime dhe pagesa dhe mbaj çdo lëvizje të sinkronizuar.", ar: "تتبع التقدم وسجّل الاستثمارات والمدفوعات وحافظ على مزامنة كل حركة.", pt: "Acompanhe o progresso, registe investimentos e pagamentos e mantenha cada movimento sincronizado.", it: "Monitora i progressi, registra investimenti e pagamenti e mantieni ogni movimento sincronizzato.", ru: "Отслеживайте прогресс, регистрируйте инвестиции и платежи и синхронизируйте каждое движение." },
  "Tracked products and materials": { de: "Verfolgte Produkte und Materialien", es: "Productos y materiales seguidos", sq: "Produkte dhe materiale të gjurmuara", ar: "المنتجات والمواد المتتبعة", pt: "Produtos e materiais acompanhados", it: "Prodotti e materiali monitorati", ru: "Отслеживаемые товары и материалы" },
  "Trailing completed-month pace": { de: "Tempo abgeschlossener Folgemonate", es: "Ritmo de meses completados recientes", sq: "Ritmi i muajve të përfunduar pasues", ar: "وتيرة الأشهر المكتملة الأخيرة", pt: "Ritmo dos meses concluídos recentes", it: "Ritmo dei mesi completati recenti", ru: "Темп последних завершённых месяцев" },
  "Transaction categories": { de: "Transaktionskategorien", es: "Categorías de transacciones", sq: "Kategoritë e transaksioneve", ar: "فئات المعاملات", pt: "Categorias de transações", it: "Categorie delle transazioni", ru: "Категории транзакций" },
  "Transaction history. The newest ten transactions are visible first; scroll for older records.": { de: "Transaktionsverlauf. Die neuesten zehn Transaktionen werden zuerst angezeigt; für ältere Einträge scrollen.", es: "Historial de transacciones. Las diez transacciones más recientes aparecen primero; desplázate para ver registros anteriores.", sq: "Historiku i transaksioneve. Dhjetë transaksionet më të reja shfaqen të parat; lëviz për regjistrimet më të vjetra.", ar: "سجل المعاملات. تظهر أحدث عشر معاملات أولًا؛ مرّر لعرض السجلات الأقدم.", pt: "Histórico de transações. As dez transações mais recentes aparecem primeiro; desloque para ver registos mais antigos.", it: "Cronologia delle transazioni. Le dieci transazioni più recenti sono visibili per prime; scorri per i record precedenti.", ru: "История транзакций. Сначала показаны десять самых новых; прокрутите для просмотра более старых записей." },
  "Transaction saved, but the reusable shortcut could not be created.": { de: "Transaktion gespeichert, aber die wiederverwendbare Abkürzung konnte nicht erstellt werden.", es: "Transacción guardada, pero no se pudo crear el acceso rápido reutilizable.", sq: "Transaksioni u ruajt, por shkurtorja e ripërdorshme nuk mund të krijohej.", ar: "تم حفظ المعاملة، لكن تعذر إنشاء الاختصار القابل لإعادة الاستخدام.", pt: "Transação guardada, mas não foi possível criar o atalho reutilizável.", it: "Transazione salvata, ma non è stato possibile creare la scorciatoia riutilizzabile.", ru: "Транзакция сохранена, но не удалось создать повторно используемый шаблон." },
  "Transactions recorded": { de: "Erfasste Transaktionen", es: "Transacciones registradas", sq: "Transaksionet e regjistruara", ar: "المعاملات المسجلة", pt: "Transações registadas", it: "Transazioni registrate", ru: "Зарегистрированные транзакции" },
  "transactions?": { de: "Transaktionen?", es: "¿transacciones?", sq: "transaksione?", ar: "معاملات؟", pt: "transações?", it: "transazioni?", ru: "транзакции?" },
