  "Use at least eight characters for your password.": { de: "Verwende mindestens acht Zeichen für dein Passwort.", es: "Usa al menos ocho caracteres para tu contraseña.", sq: "Përdor të paktën tetë karaktere për fjalëkalimin tënd.", ar: "استخدم ثمانية أحرف على الأقل لكلمة المرور.", pt: "Utiliza pelo menos oito caracteres para a tua palavra-passe.", it: "Usa almeno otto caratteri per la password.", ru: "Используйте не менее восьми символов для пароля." },
  "Use debt reduction to move the investable starting position above zero.": { de: "Nutze den Schuldenabbau, um die investierbare Ausgangsposition über null zu bringen.", es: "Usa la reducción de deuda para llevar la posición inicial invertible por encima de cero.", sq: "Përdor uljen e borxhit për ta çuar pozicionin fillestar të investueshëm mbi zero.", ar: "استخدم خفض الديون لرفع نقطة البداية القابلة للاستثمار فوق الصفر.", pt: "Utiliza a redução da dívida para elevar a posição inicial investível acima de zero.", it: "Usa la riduzione del debito per portare la posizione iniziale investibile sopra lo zero.", ru: "Используйте сокращение долга, чтобы вывести стартовую инвестиционную позицию выше нуля." },
  "Use PDF, Word, Excel, CSV, TXT, PNG, JPG or WEBP documents.": { de: "Verwende PDF-, Word-, Excel-, CSV-, TXT-, PNG-, JPG- oder WEBP-Dokumente.", es: "Usa documentos PDF, Word, Excel, CSV, TXT, PNG, JPG o WEBP.", sq: "Përdor dokumente PDF, Word, Excel, CSV, TXT, PNG, JPG ose WEBP.", ar: "استخدم مستندات PDF أو Word أو Excel أو CSV أو TXT أو PNG أو JPG أو WEBP.", pt: "Utiliza documentos PDF, Word, Excel, CSV, TXT, PNG, JPG ou WEBP.", it: "Usa documenti PDF, Word, Excel, CSV, TXT, PNG, JPG o WEBP.", ru: "Используйте документы PDF, Word, Excel, CSV, TXT, PNG, JPG или WEBP." },
  "Use quick choices": { de: "Schnellauswahl verwenden", es: "Usar opciones rápidas", sq: "Përdor zgjedhjet e shpejta", ar: "استخدام الخيارات السريعة", pt: "Usar opções rápidas", it: "Usa scelte rapide", ru: "Использовать быстрый выбор" },
  "Use scenario comparisons to understand which contribution changes have the largest effect.": { de: "Nutze Szenariovergleiche, um zu verstehen, welche Beitragsänderungen den größten Effekt haben.", es: "Usa comparaciones de escenarios para entender qué cambios en las aportaciones tienen el mayor efecto.", sq: "Përdor krahasimet e skenarëve për të kuptuar se cilat ndryshime të kontributeve kanë ndikimin më të madh.", ar: "استخدم مقارنات السيناريوهات لفهم تغييرات المساهمات ذات التأثير الأكبر.", pt: "Utiliza comparações de cenários para perceber quais alterações nas contribuições têm maior impacto.", it: "Usa i confronti tra scenari per capire quali variazioni dei contributi hanno l'effetto maggiore.", ru: "Используйте сравнение сценариев, чтобы понять, какие изменения взносов дают наибольший эффект." },
  "Use the Monthly Planner to allocate income across expenses, savings, debt and goals.": { de: "Nutze den Monatsplaner, um Einnahmen auf Ausgaben, Sparen, Schulden und Ziele zu verteilen.", es: "Usa el Planificador mensual para distribuir los ingresos entre gastos, ahorro, deuda y objetivos.", sq: "Përdor Planifikuesin Mujor për të shpërndarë të ardhurat mes shpenzimeve, kursimeve, borxhit dhe objektivave.", ar: "استخدم المخطط الشهري لتوزيع الدخل بين المصروفات والادخار والديون والأهداف.", pt: "Utiliza o Planeador Mensal para distribuir o rendimento entre despesas, poupanças, dívida e objetivos.", it: "Usa il Pianificatore mensile per distribuire le entrate tra spese, risparmi, debiti e obiettivi.", ru: "Используйте Ежемесячный планировщик для распределения доходов между расходами, сбережениями, долгами и целями." },
  "Use the projection as a planning guide, not a guaranteed outcome.": { de: "Nutze die Projektion als Planungshilfe, nicht als garantiertes Ergebnis.", es: "Usa la proyección como guía de planificación, no como un resultado garantizado.", sq: "Përdor projeksionin si udhëzues planifikimi, jo si rezultat të garantuar.", ar: "استخدم التوقع كدليل للتخطيط، وليس كنتيجة مضمونة.", pt: "Utiliza a projeção como guia de planeamento, não como um resultado garantido.", it: "Usa la proiezione come guida di pianificazione, non come risultato garantito.", ru: "Используйте прогноз как ориентир для планирования, а не как гарантированный результат." },
  "Used in operations": { de: "Im Betrieb verwendet", es: "Usado en operaciones", sq: "Përdoret në operacione", ar: "مستخدم في العمليات", pt: "Utilizado nas operações", it: "Utilizzato nelle operazioni", ru: "Используется в операционной деятельности" },
  "USER MANAGEMENT": { de: "BENUTZERVERWALTUNG", es: "GESTIÓN DE USUARIOS", sq: "MENAXHIMI I PËRDORUESVE", ar: "إدارة المستخدمين", pt: "GESTÃO DE UTILIZADORES", it: "GESTIONE UTENTI", ru: "УПРАВЛЕНИЕ ПОЛЬЗОВАТЕЛЯМИ" },
