  "What deserves attention first": { de: "Was zuerst Aufmerksamkeit verdient", es: "Qué merece atención primero", sq: "Çfarë meriton vëmendje së pari", ar: "ما الذي يستحق الاهتمام أولًا", pt: "O que merece atenção primeiro", it: "Cosa merita attenzione per prima", ru: "Что требует внимания в первую очередь" },
